  140	        // is the session's own.
  141	        if (! $underAttack) {
  142	            foreach ($planets as $planet) {
  143	                $power = $this->powerFromYard($planet);
  144	                if ($power !== null) {
  145	                    return $power;
  146	                }
  147	            }
  148	        }
  149	
  150	        foreach ($planets as $planet) {
  151	            $planet->updateResources(false);
  152	
  153	            // Whether this planet wants a wall, and how big. Asked before the wall is composed so
  154	            // the same answer sizes both the reactive and the standing defence below.
  155	            $need = $this->defenseNeed->evaluate($player, $planet);
  156	
  157	            // Cargo first, and only while the account owns no ship at all: a fleet begins with
  158	            // one hull that can carry. A planet that owns nothing but cannot queue one yet still
  159	            // falls through -- defence is reactive and standing, and waiting for a hull is what
  160	            // left a fleetless account with no wall of its own.
  161	            if ($this->ownsNoShip($planet)) {
  162	                $cargo = $this->bestCargo($player, $planet);
  163	                if ($cargo !== null) {
  164	                    return $this->unit($planet, $cargo, 'role:cargo:'.$cargo->machine_name);
  165	                }
  166	            }
  167	
  168	            // Defence is reactive and time-sensitive: an inbound hostile makes it worth buying
  169	            // before anything else on this planet, and the host's own "under attack" is the
  170	            // trigger, so the module keeps no mission-type list.
  171	            if ($underAttack) {
  172	                $defense = $this->defenseComposition->plan($player, $planet, $need);
  173	                if ($defense !== null) {
  174	                    return $this->unit($planet, $defense->unit, 'role:defense:'.$defense->unit->machine_name, $defense->amount);
  175	                }
  176	            }
  177	
  178	            // Expansion: a colony ship once a fleet exists, the account has room, and none is
  179	            // already owned. One colony ship is the second planet every later fleet move needs.
  180	            if (! $this->ownsColonyShip($planet) && $player->planets->planetCount() < $player->getMaxPlanetAmount()) {
  181	                $colonyShip = ObjectService::getUnitObjectByMachineName(ColonisationMission::getRequiredShipMachineNames()[0]);
  182	                if ($this->queueable($planet, $colonyShip)) {
  183	                    return $this->unit($planet, $colonyShip, 'role:colony');
  184	                }
  185	            }
  186	
  187	            // Scouting: a probe once a fleet exists, so the account can start seeing neighbours.
  188	            if (! $this->ownsProbe($planet)) {
  189	                $probe = ObjectService::getUnitObjectByMachineName(EspionageMission::getRequiredShipMachineNames()[0]);
  190	                if ($this->queueable($planet, $probe)) {
  191	                    return $this->unit($planet, $probe, 'role:probe');
  192	                }
